"id": "9e0dcef9-4266-5c6d-868e-53368b34f630"}, {"name": "王宗侃", "aliases": ["田师侃"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：王宗侃。", "biography": null, "status": "draft", "id": "75b99890-6c36-5356-ba40-854c4077a4e9"}, {"name": "王宗涤", "aliases": ["华洪"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺二年条所见人物：王宗涤。", "biography": null, "status": "draft", "id": "c4df8006-3248-5260-8c74-b2035f076315"}, {"name": "王宗瑶", "aliases": ["姜郅"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：王宗瑶。", "biography": null, "status": "draft", "id": "eec2fc8f-2f8b-56d8-a6ed-34c55a26aa3c"}, {"name": "杨晟", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：杨晟。", "biography": null, "status": "draft", "id": "93faf005-49ad-5fd8-82c5-75a556805ef0"}, {"name": "杨守亮", "aliases": ["訾亮"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：杨守亮。", "biography": null, "status": "draft", "id": "794556be-c340-512f-923f-61f100db55df"}, {"name": "符昭", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259景福元年条所见人物：符昭。", "biography": null, "status": "draft", "id": "638bd86a-da8e-5f04-ae67-acd7335bb72f"}, {"name": "郑延昌", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259景福元年条所见人物：郑延昌。", "biography": null, "status": "draft", "id": "33cc9170-06f5-5723-acfc-e8a8f3f1016e"}, {"name": "郑从谠", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：郑从谠。", "biography": null, "status": "draft", "id": "15f99f06-f58e-5b7f-8845-549c1edaad2d"}, {"name": "杨子实", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259景福元年条所见人物：杨子实。", "biography": null, "status": "draft", "id": "d05038a2-b9cc-5816-88bc-5b522f996fcd"}, {"name": "杨子迁", "aliases": [], "