INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "朱全忠奏贬赵克裕，以张全义兼河阳", "start_year": 892, "end_year": 892, "time_original": "892年二月条；具体日未载", "dynasty": "唐", "description": "朱全忠奏请贬河阳节度使赵克裕，以佑国节度使张全义兼河阳节度使。", "phases": [], "location_name": "河阳、佑国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "fa7baf7d-0923-5a9a-aaeb-43df31aba2a8"}, {"title": "孙儒围宣州", "start_year": 892, "end_year": 892, "time_original": "892年二月条；具体日未载", "dynasty": "唐", "description": "孙儒围攻宣州。", "phases": [], "location_name": "宣州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "ea52960e-f1c1-56fc-a6a6-d680e79af659"}, {"title": "刘建锋随孙儒出征，陈可言据常州的追叙", "start_year": null, "end_year": null, "time_original": "初；确年日未载", "dynasty": "唐", "description": "《通鉴》追述刘建锋原为孙儒守常州，后来率兵从孙儒攻杨行密，甘露镇使陈可言率千人占常州。", "phases": [], "location_name": "常州、甘露镇", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "b7b3cdac-b1c0-56d9-a3bc-a883c749937c"}, {"title": "张训袭常州手刃陈可言", "start_year": null, "end_year": null, "time_original": "段内初之后；确年日未定", "dynasty": "唐", "description": "张训突然率军至常州城下，陈可言仓促出迎，张训亲手杀之，取得常州。", "phases": [], "location_name": "常州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "a0dfbeb9-db76-5638-a00f-7f92a25f2f62"}, {"title": "杨行密别将取得润州", "start_year": null, "end_year": null, "time_original": "段内初之后；确年日未定", "dynasty": "唐", "description": "杨行密另一将领取得润州。", "phases": [], "location_name": "润州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "cf7c23e1-4e62-56f9-85fc-78c888eaae54"}, {"title": "朱全忠连年攻时溥，三州战水灾饥死", "start_year": null, "end_year": null, "time_original": "连年；起始与逐次确年日未载", "dynasty": "唐", "description": "《通鉴》述朱全忠连年攻时溥，三州居民不得耕获，外镇援军无功，又遇水灾，书载人死十之六七。", "phases": [], "location_name": "涂州、泗州、濠州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "793377d4-9b76-515d-89f2-72b0520a2cde"}, {"title": "时溥求和，朱全忠要求移镇", "start_year": 892, "end_year": 892, "time_original": "892年二月条；具体日未载", "dynasty": "唐", "description": "时溥困迫向朱全忠求和，朱全忠要求其移镇才可，时溥答应；朱全忠奏请将时溥移它镇，命大臣镇徐州。", "phases": [], "location_name": "徐州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e4d54c35-5a07-5f53-9cdf-7df937ef7ba3"}, {"title": "刘崇望受任感化，时溥拒诏使其折返", "start_year": 892, "end_year": 892, "time_original": "892年二月条；移镇议后", "dynasty": "唐", "description": "朝廷任刘崇望同平章事、感化节度使，任时溥为太子太师。时溥怕朱全忠欺骗杀他，据城不奉诏，刘崇望到华阴后返回。", "phases": [], "location_name": "徐州、华阴", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d825a1d9-fac8-5eb9-87f6-ffa111121d70"}, {"title": "赵德諲去世，赵匡凝继任", "start_year": 892, "end_year": 892, "time_original": "892年二月条；具体日未载", "dynasty": "唐", "description": "忠义节度使赵德諲去世，其子赵匡凝继任。", "phases": [], "location_name": "忠义", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "ee506ef3-0bcf-5d80-80c4-6029ce880813"}, {"title": "王潮遣王彦复王审知攻福州", "start_year": 892, "end_year": 892, "time_original": "892年二月条；具体日未载", "dynasty": "唐", "description": "范晖骄侈失众心，王潮以从弟王彦复为都统、弟王审知为都监，率军攻福州。居民请输米饷军，平湖洞及滨海蛮夷用兵船相助。", "phases": [], "location_name": "福州、平湖洞、滨海", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "259dacab-6c1f-5d9a-b259-679f907caacb"}, {"title": "王宗裕等五万人攻彭州围杨晟", "start_year": 892, "end_year": 892, "time_original": "892年二月辛丑", "dynasty": "唐", "description": "王建遣族子嘉州刺史王宗裕、雅州刺史王宗侃、华洪、茂州刺史王宗瑶率五万人攻彭州，杨晟迎战败，诸将围之。", "phases": [], "location_name": "彭州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "3cbfb062-4d06-571e-8f83-0f6988d7a837"}, {"title": "华洪更鼓疑兵退符昭救成都", "start_year": 892, "end_year": 892, "time_original": "892年二月辛丑后条", "dynasty": "唐", "description": "杨守亮遣符昭救杨晟，符昭直向成都营三学山。王建急召华洪返，华洪后军未集，以数百人夜近敌营数里，多击更鼓，符昭误以蜀军大至，连夜逃走。", "phases": [], "location_name": "成都、三学山", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "cb2204e6-d7f7-5cd5-8dbd-e64d347bc7a4"}, {"title": "郑延昌三月拜相", "start_year": 892, "end_year": 892, "time_original": "892年三月", "dynasty": "唐", "description": "朝廷以户部尚书郑延昌为中书侍郎、同平章事。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "d5a7dc13-4c15-53ab-93c5-5523da60717e"}, {"title": "杨子实子迁子钊率二万人降王建", "start_year": 892, "end_year": 892, "time_original": "892年三月壬子", "dynasty": "唐", "description": "杨守亮假子杨子实、杨子迁、杨子钊从渠州引兵救杨晟，得知杨守亮必败，率众二万投降王建。", "phases": [], "location_name": "渠州、西川", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "c6c69eb9-2ae1-50c7-81fb-a5302e19710c"}]'::jsonb)
